import {find,isLocked} from '../document/model.js';
import {currentMesh,editMesh} from '../scene/mesh-edit.js';
import {readRecentColours,normalColour} from './object-colour.js';
import {ImmediateColourSession,bindImmediateColour} from './immediate-colour.js';
export function showMeshColour(a){
 const n=find(a.doc,a.selected[0]);if(!n?.mesh||isLocked(a.doc,n.id))return;a.activeColourDialog?.close();a.motionRecorder?.cancel({render:false});a.pause();a.properties.flush();
 const index=Math.min(a.activeMesh||0,currentMesh(n,a.time).points.length-1),initial=currentMesh(n,a.time).points[index].color;
 const palette=['#ffffff','#000000','#ff625f','#ffb84d','#ffe066','#65d49a','#59cbe8','#6477eb','#b87ee8','#ed85b2'];let recent=[];try{recent=readRecentColours(localStorage);}catch{}if(!recent.length)recent=a.recentColours||[];
 const d=a.dialog('Mesh point '+(index+1)+' colour',`<form><p>Choose a colour; it applies immediately. Undo restores the previous shade.</p><div class="mesh-palette">${palette.map(c=>`<button type="button" data-swatch="${c}" aria-label="Colour ${c}" style="background:${c};width:44px;height:44px"></button>`).join('')}</div><div data-colour-preview style="height:48px;margin:12px 0;border-radius:8px;background:${initial}"></div>${['Red','Green','Blue'].map((c,i)=>`<label>${c}<input aria-label="${c}" data-channel="${i}" type="range" min="0" max="255" value="${parseInt(initial.slice(1+i*2,3+i*2),16)}"></label>`).join('')}<label>Hex colour<input name="colour" aria-label="Hex colour" value="${initial}" required></label><div class="dialog-actions"><button type="button" data-close>Done</button></div></form>`,undefined,{modal:false});d.classList.add('object-colour-dialog');a.activeColourDialog=d;
 d.querySelector('.mesh-palette').insertAdjacentHTML('beforebegin',`<h3>Last 10 colours</h3><div class="mesh-palette">${recent.length?recent.slice(0,10).map(c=>`<button type="button" data-swatch="${c}" aria-label="Recent colour ${c}" style="background:${c};width:44px;height:44px"></button>`).join(''):'<small>Chosen colours appear here.</small>'}</div><h3>Swatches</h3>`);
 const session=new ImmediateColourSession(a,{ids:[n.id],ownerId:n.id,label:'Mesh point colour',apply(color,time){const current=find(a.doc,n.id);if(!current?.mesh||index>=currentMesh(current,time).points.length)return;editMesh(current,time,m=>{m.points[index].color=color;return m;});}});
 const channels=[...d.querySelectorAll('[data-channel]')],hex=d.querySelector('[name=colour]'),preview=d.querySelector('[data-colour-preview]');
 const update=(color,discrete=false,keepHex=false)=>{color=normalColour(color);if(!color)return;if(!session.update(color,discrete)){session.close();d.close();return;}if(!keepHex)hex.value=color;preview.style.background=color;channels.forEach((el,i)=>el.value=parseInt(color.slice(1+i*2,3+i*2),16));};
 d.querySelectorAll('[data-swatch]').forEach(el=>el.onclick=()=>update(el.dataset.swatch,true));channels.forEach(el=>el.oninput=()=>update('#'+channels.map(x=>Math.max(0,Math.min(255,Number(x.value)||0)).toString(16).padStart(2,'0')).join('')));hex.oninput=()=>update(hex.value,false,true);bindImmediateColour(a,d,session);return d;
}
